    },
    {
      "card_ids": ["C11"],
      "claim": "Penicillin G showed CSF concentrations only 1-2% of plasma due to faster outward clearance, providing direct evidence of limited CNS access for that compound.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "Prediction is pass: the majority of transferred direct in-vivo records show brain uptake, CSF penetration, or equivalent plasma-brain exposure. One high-scoring molecule (penicillin G) shows limited normal-state CSF access, but the overall direct evidence strongly supports meaningful CNS access.",
  "evidence_gaps": [
    "Molecule 2 is mixed: positive CSF detection in neonates and inflamed meninges contrasts with low CSF/serum ratios in normal adults; its negative direction is the main contradictory evidence.",
    "Qualitative brain or CSF detection is treated as sufficient for meaningful access, without a defined therapeutic threshold."
  ],
